#define SANS_PIERWSZY	32
#define SANS_OSTATNI	126

struct glif_sans {
	unsigned short szer, wys;	/* rozmiar maski alfa */
	short lewo, gora;		/* przesuniecie wzgledem punktu pisania */
	unsigned short zaliczka;	/* o ile przesunac sie dalej */
	unsigned int offset;		/* poczatek w SANS_ALFA */
};

